      "replace": "def _matches_scope_prefix(scope_name: str, prefix: str) -> bool:
    """Return whether a scope matches a prefix using namespace boundaries.

    Matching is now case‑insensitive: both the provided scope name and the
    allow‑list prefix are compared in lower‑case.
    """
    # Normalize to lower‑case to make matching case‑insensitive.
    scope_name_lc = scope_name.lower()
    prefix_lc = prefix.lower()
    return scope_name_lc == prefix_lc or scope_name_lc.startswith(f"{prefix_lc}.")"
