  "test": "import pytest
from types import SimpleNamespace
from langfuse.span_filter import is_known_llm_instrumentor

def _make_span(scope_name: str):
    scope = SimpleNamespace(name=scope_name)
    return SimpleNamespace(instrumentation_scope=scope, attributes={})

@pytest.mark.parametrize(
    "scope_name",
    [
        "AI",  # upper‑case exact match
        "OpenInference.Instrumentation.Agno.Worker",  # mixed case prefix descendant
        "opentelemetry.Instrumentation.OpenAI.V1",  # another mixed case example
    ],
)
def test_is_known_llm_instrumentor_case_insensitive(scope_name):
    span = _make_span(scope_name)
    assert is_known_llm_instrumentor(span) is True
